B.ara=new A.c6("\u2600\ufe0f","Matahari","Sun","Matahari adalah bintang terdekat dengan Bumi.","The Sun is the star closest to Earth.",B.cR)
B.arf=new A.c6("\ud83c\udf19","Bulan","Moon","Bulan memantulkan cahaya Matahari ke Bumi.","The Moon reflects the Sun's light onto Earth.",B.e1)
B.aqR=new A.c6("\u2b50","Bintang","Star","Bintang terdekat selain Matahari berjarak 4 tahun cahaya.","The nearest star besides the Sun is 4 light-years away.",B.cR)
B.aro=new A.c6("\ud83e\ude90","Saturnus","Saturn","Saturnus punya cincin yang terdiri dari es dan batu.","Saturn's rings are made of ice and rock.",B.c8)
B.ar8=new A.c6("\u2604\ufe0f","Komet","Comet",'Komet adalah "bola salju kotor" yang mengelilingi Matahari.','A comet is a "dirty snowball" orbiting the Sun.',B.e2)
B.ar7=new A.c6("\ud83c\udf0c","Galaksi","Galaxy","Kita tinggal di galaksi Bima Sakti.","We live in the Milky Way galaxy.",B.e1)
B.ar_=new A.c6("\ud83d\ude80","Roket","Rocket","Roket pertama ke bulan diluncurkan tahun 1969.","The first rocket to the Moon launched in 1969.",B.c8)
B.aqX=new A.c6("\ud83c\udf11","Planet Mars","Planet Mars",'Mars sering disebut "Planet Merah" karena warnanya.','Mars is often called the "Red Planet" because of its color.',B.c8)
